import { registerWebComponents } from '@domg-wc/common';
import { VlHeader } from '@domg-wc/components/compliance/next';

registerWebComponents([VlHeader]);

// ready volgt op het element zelf zodra de widget gemount is; het bubbelt niet. Vanaf dan geeft height de hoogte.
const header = document.querySelector('vl-header-next');
header.addEventListener('ready', () => {
    console.log(header.height);
});

import { registerWebComponents } from '@domg-wc/common';
import { VlHeader } from '@domg-wc/components/compliance/next';

registerWebComponents([VlHeader]);

// vl-header-next geeft applicationLinks één keer door aan de widget, na het mounten: zet de property meteen.
document.querySelector('vl-header-next').applicationLinks = [
    { label: 'Link 1', href: 'https://example.com/link1' },
    { label: 'Link 2', href: 'https://example.com/link2' },
];
